223	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
224	     * string is what gets stored and returned.
225	     *
226	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
227	     *
228	     * @param telephone the raw telephone value supplied by the client
229	     * @return the normalized E.164 telephone number
230	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
231	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
232	     *                                 digits after the {@code '+'})
233	     */
234	    private static String normalizeTelephone(String telephone) {
235	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
236	        String digits;
237	        if (cleaned.startsWith("+")) {
238	            digits = cleaned.substring(1);
239	        } else {
240	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
241	            digits = "61" + national;
242	        }
243	        if (!digits.matches("[0-9]{8,15}")) {
244	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
245	                "telephone could not be normalized to a valid E.164 number");
