279	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
280	     *                                 is not a syntactically valid address
281	     */
282	    private static String normalizeEmail(String email) {
283	        if (email == null) {
284	            return null;
285	        }
286	        if (!EMAIL_PATTERN.matcher(email).matches()) {
287	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
288	                "email must be a syntactically valid address");
289	        }
