297	     * inputs representing the same number are treated as duplicates.
298	     *
299	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
300	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
301	     * @return {@code true} if another owner already uses the telephone
302	     */
303	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
304	        for (Owner existing : this.clinicService.findAllOwners()) {
305	            if (excludeId != null && excludeId.equals(existing.getId())) {
306	                continue;
307	            }
308	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
309	                return true;
310	            }
311	        }
312	        return false;
313	    }
